 web:[['freeCodeCamp Responsive Web Design','Practise HTML, CSS, responsive layouts, and accessibility. A learning credential to consider after project practice.','Free learning and certification','https://www.freecodecamp.org/learn/']],
 security:[['CompTIA Security+','An optional broad security credential. Build networking and practical security foundations before considering an exam.','Paid exam; check current provider requirements','https://www.comptia.org/en-us/certifications/security/']],
