 cloud:[['AWS Certified Cloud Practitioner','A foundational cloud credential to consider if your target opportunities use AWS. Pair study with hands-on work.','Paid exam; check current provider details','https://aws.amazon.com/certification/certified-cloud-practitioner/']]
