const domainFamily=d=>GUIDES[d]?d:['AI / Machine Learning','Business Analytics','Bioinformatics','Quantitative Research','Operations Research','Actuarial Studies'].includes(d)?'Data Analytics':['Mobile Development','DevOps','Software Testing','Game Development','Database Engineering','Embedded Systems','IoT Systems','FinTech'].includes(d)?'Software Engineering':['Graphic Design','Motion Design','Interaction Design','Product Design','Service Design','UX Research'].includes(d)?'UI/UX Design':['Financial Analysis','Audit & Assurance','Taxation','Banking Operations'].includes(d)?'Accounting':['Content Strategy','Journalism','Entrepreneurship','Product Management','Human Resources','Operations & Supply Chain','Public Policy Research','Scientific Communication'].includes(d)?'Marketing':'Mechanical Design';
function guideFor(d){return GUIDES[domainFamily(d)]}
function certificationFor(d){return /Cyber/.test(d)?CERTS.security:/Cloud|DevOps/.test(d)?CERTS.cloud:/Data|Analytics/.test(d)?CERTS.data:/Web/.test(d)?CERTS.web:[]}
